package com.worknotice.alarm;
import android.content.*;
import android.os.*;
import android.provider.Settings;
import org.json.JSONObject;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.*;
import java.time.Instant;
import java.util.*;
import static org.junit.Assert.*;
import static org.robolectric.Shadows.shadowOf;

@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,manifest=Config.NONE,application=android.app.Application.class)
@LooperMode(LooperMode.Mode.PAUSED)
public class MonitoringTests {
    Context c;MonitoringStore store;static final String SESSION="a".repeat(64);
    static JSONObject root(String mode,long rev,String session,long start,String command) throws Exception {return new JSONObject().put("serverNow",100000).put("pairedAt",1000).put("monitoring",new JSONObject().put("mode",mode).put("revision",rev).put("session_id",session).put("starts_at_ms",start).put("last_command_id",command).put("urgent_consent",mode.equals("OFF")?0:1));}
    @Before public void setup(){c=RuntimeEnvironment.getApplication();Settings.Global.putInt(c.getContentResolver(),Settings.Global.BOOT_COUNT,1);store=new MonitoringStore(c);}
    Map<String,String> event(long occurred,long issued,long expires){Map<String,String> data=new HashMap<>();data.put("monitoringSessionId",SESSION);data.put("monitoringRevision","1");data.put("monitoringStartsAtMs","100000");data.put("monitoringMode","IMMEDIATE");data.put("serverNowMs",String.valueOf(store.serverNow()));data.put("occurredAt",Instant.ofEpochMilli(occurred).toString());data.put("issuedAt",Instant.ofEpochMilli(issued).toString());data.put("expiresAt",Instant.ofEpochMilli(expires).toString());return data;}
    @Test public void scheduledDoesNotBecomeActiveUntilTrustedStart() throws Exception {store.update(root("SCHEDULED",1,SESSION,160000,"c"),0);assertEquals("SCHEDULED",store.state());assertFalse(store.active());shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofSeconds(60));assertEquals("ACTIVE",store.state());assertTrue(new MonitoringStore(c).active());}
    @Test public void startTransitionDoesNotCreateNotificationOrCommand() throws Exception {store.update(root("SCHEDULED",1,SESSION,160000,"c"),0);shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofSeconds(60));assertNull(store.pending());assertEquals(0,c.getSystemService(android.app.NotificationManager.class).getActiveNotifications().length);}
    @Test public void activeNewEventAcceptedButPreStartDelayedEventRejected() throws Exception {store.update(root("IMMEDIATE",1,SESSION,100000,"c"),0);assertTrue(store.accept(event(100000,100000,220000)));assertFalse(store.accept(event(99000,100000,219000)));}
    @Test public void oldSessionAndRevisionFailClosed() throws Exception {store.update(root("IMMEDIATE",1,SESSION,100000,"c"),0);var data=event(100000,100000,220000);data.put("monitoringRevision","0");assertFalse(store.accept(data));data.put("monitoringRevision","1");data.put("monitoringSessionId","b".repeat(64));assertFalse(store.accept(data));}
    @Test public void expiredDelayedFcmIsRejected() throws Exception {store.update(root("IMMEDIATE",1,SESSION,100000,"c"),0);shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofSeconds(121));assertFalse(store.accept(event(100000,100000,220000)));}
    @Test public void closeImmediatelyRejectsAndPersistsOffline() throws Exception {store.update(root("IMMEDIATE",1,SESSION,100000,"c"),0);store.command("OFF",0,false,1000);assertFalse(store.active());assertFalse(new MonitoringStore(c).accept(event(100000,100000,220000)));assertNotNull(new MonitoringStore(c).pending());}
    @Test public void delayedOldSuccessCannotClearCancelTombstone() throws Exception {store.update(root("IMMEDIATE",1,SESSION,100000,"old"),0);store.command("OFF",0,false,1000);store.update(root("IMMEDIATE",1,SESSION,100000,"old"),0);assertTrue(store.ended());}
    @Test public void pendingRetryRetainsExactCommandIdAndDelay() throws Exception {store.update(root("OFF",0,"",0,""),0);var command=store.command("SCHEDULED",480,true,1000);assertEquals(command.toString(),new MonitoringStore(c).pending().toString());assertEquals(480,store.pending().getInt("delayMinutes"));try{store.command("IMMEDIATE",0,true,1000);fail();}catch(IllegalStateException expected){}}
    @Test public void preparedConsentSurvivesScheduledToActiveWithoutRevisionChange() throws Exception {store.update(root("OFF",0,"",0,""),0);var command=store.command("SCHEDULED",1,true,1000);store.update(root("SCHEDULED",1,SESSION,160000,command.getString("commandId")),0);assertTrue(FsiSettings.enabled(c));assertNull(store.pending());shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofSeconds(60));assertTrue(FsiSettings.enabled(c));assertEquals(1,store.revision());}
    @Test public void rebootUsesConfirmedOffsetInsteadOfPermanentlyDisabling() throws Exception {store.update(root("SCHEDULED",1,SESSION,100000,"c"),0);FsiSettings.consent(c);Settings.Global.putInt(c.getContentResolver(),Settings.Global.BOOT_COUNT,2);assertTrue(new MonitoringStore(c).active());assertTrue(FsiSettings.enabled(c));var data=event(100000,100000,220000);data.put("monitoringMode","SCHEDULED");assertTrue(store.accept(data));}
    @Test public void outOfOrderSettingCannotReplaceNewRevision() throws Exception {store.update(root("IMMEDIATE",2,"b".repeat(64),100000,"new"),0);assertFalse(store.update(root("SCHEDULED",1,SESSION,160000,"old"),0));assertEquals(2,store.revision());}
    @Test public void manualStopDoesNotEndMonitoring() throws Exception {store.update(root("IMMEDIATE",1,SESSION,100000,"c"),0);PendingAlarmStore ledger=new PendingAlarmStore(c);String event="d".repeat(64);ledger.register(event,SystemClock.elapsedRealtime()+10000,1000);ledger.stopped(event);assertTrue(store.active());assertTrue(store.accept(event(100000,100000,220000)));}
    @Test public void versionChangeInvalidatesFsiConsent() throws Exception {store.update(root("IMMEDIATE",1,SESSION,100000,"c"),0);FsiSettings.consent(c);store.update(root("SCHEDULED",2,"b".repeat(64),200000,"other"),0);assertFalse(FsiSettings.enabled(c));}
    @Test public void noHeartbeatDataIsNotInventedByMonitoring(){assertEquals("{}",new AlarmPreferencesRepository(c).status());assertEquals("OFF",store.state());}
    @Test public void firstEventCanReconcileCommandAcceptedBeforeProcessDeath() throws Exception {store.update(root("OFF",0,"",0,""),0);var command=store.command("IMMEDIATE",0,true,1000);var data=event(100000,100000,220000);data.put("monitoringCommandId",command.getString("commandId"));assertTrue(new MonitoringStore(c).accept(data));assertNull(store.pending());assertTrue(FsiSettings.enabled(c));}
    @Test public void explicitCancelAfterConflictUsesNewRevisionButStaysStopped() throws Exception {store.update(root("OFF",0,"",0,""),0);var off=store.command("OFF",0,false,1000);assertEquals(off.toString(),store.command("OFF",0,false,1000).toString());store.update(root("IMMEDIATE",1,SESSION,100000,"other"),0);assertTrue(store.ended());var newer=store.command("OFF",0,false,1000);assertEquals(1,newer.getLong("expectedRevision"));assertNotEquals(off.getString("commandId"),newer.getString("commandId"));assertFalse(store.active());}
    @Test public void newExplicitMonitoringAfterPriorOffCanReconcileFromFirstFcm() throws Exception {store.update(root("OFF",1,"b".repeat(64),0,"old-off"),0);store.command("OFF",0,false,1000);var off=store.pending();store.update(root("OFF",2,"c".repeat(64),0,off.getString("commandId")),0);var on=store.command("IMMEDIATE",0,true,1000);var data=event(100000,100000,220000);data.put("monitoringRevision","3");data.put("monitoringCommandId",on.getString("commandId"));assertTrue(store.accept(data));assertFalse(store.ended());}
    @Test public void manualFallbackUsesNewAuthoritativeStateInsteadOfDisabledLegacyProjection() throws Exception {store.update(root("IMMEDIATE",1,SESSION,100000,"c"),0);JSONObject active=store.setting().put("state","ACTIVE");assertTrue(store.matchesActive(active));assertFalse(store.matchesActive(active.put("state","SCHEDULED")));assertFalse(store.matchesActive(active.put("state","ACTIVE").put("revision",2)));assertFalse(store.matchesActive(null));}
    @Test public void queuedAutoStartRechecksEndAndManualFallbackRechecksRevision() throws Exception {store.update(root("IMMEDIATE",1,SESSION,100000,"c"),0);PendingAlarmStore ledger=new PendingAlarmStore(c);String id="d".repeat(64);assertTrue(ledger.register(id,SystemClock.elapsedRealtime()+10000,1000));assertTrue(ledger.autoEligible(id));String nonce=ledger.offer(id);store.update(root("IMMEDIATE",2,"b".repeat(64),100000,"new"),0);assertFalse(ledger.autoEligible(id));assertEquals(FallbackAlarm.Decision.DISABLED,ledger.claim(id,nonce,1000,true,true));store.command("OFF",0,false,1000);assertFalse(ledger.autoEligible(id));}
    @Test public void confirmedScheduleAndConsentAreStoredAtomicallyWithoutLegacyPrefs() throws Exception {store.update(root("OFF",0,"",0,""),0);var command=store.command("SCHEDULED",480,true,1000);store.update(root("SCHEDULED",1,SESSION,100000+480*60000,command.getString("commandId")),0);c.getSharedPreferences("fsi-v1",0).edit().clear().commit();assertNull(new MonitoringStore(c).pending());assertTrue(new MonitoringStore(c).fsiDeclared());assertTrue(FsiSettings.enabled(c));}
}
